package com.highpass.runspot.chat.repository;import com.highpass.runspot.chat.domain.*;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface ChatRoomMemberRepository extends JpaRepository<ChatRoomMember,Long>{@EntityGraph(attributePaths={"room","room.session","room.host","room.guest"})List<ChatRoomMember> findByUserIdAndLeftAtIsNullOrderByRoomLastMessageAtDesc(Long userId);Optional<ChatRoomMember> findByRoomIdAndUserIdAndLeftAtIsNull(Long roomId,Long userId);@EntityGraph(attributePaths={"user"})List<ChatRoomMember> findByRoomIdAndLeftAtIsNull(Long roomId);boolean existsByRoomIdAndUserIdAndLeftAtIsNull(Long roomId,Long userId);@Query("select m.room.id as roomId,count(m.id) as memberCount from ChatRoomMember m where m.leftAt is null and m.room.id in :roomIds group by m.room.id")List<RoomMemberCount> countActiveByRoomIds(@Param("roomIds")Collection<Long> roomIds);}
